from __future__ import annotations
import json
import re

def _safe_id(value: str, fallback='omni.app') -> str:
    cleaned=re.sub(r'[^A-Za-z0-9_.]','',value).strip('.')
    return cleaned or fallback

def android_project(*, app_name: str='Omni App', application_id: str='ai.omnicreator.app') -> dict[str,str]:
    app_id=_safe_id(application_id); package_path=app_id.replace('.','/')
    return {
        'settings.gradle.kts':'pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }\ndependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }\nrootProject.name="OmniApp"\ninclude(":app")\n',
        'build.gradle.kts':'plugins { id("com.android.application") version "8.7.3" apply false; id("org.jetbrains.kotlin.android") version "2.0.21" apply false }\n',
        'app/build.gradle.kts':f'''plugins {{ id("com.android.application"); id("org.jetbrains.kotlin.android") }}\nandroid {{ namespace="{app_id}"; compileSdk=35\n defaultConfig {{ applicationId="{app_id}"; minSdk=26; targetSdk=35; versionCode=1; versionName="1.0" }}\n buildTypes {{ release {{ isMinifyEnabled=false; signingConfig = signingConfigs.findByName("release") }} }} }}\n''',
        'app/src/main/AndroidManifest.xml':f'''<manifest xmlns:android="http://schemas.android.com/apk/res/android"><application android:theme="@style/AppTheme" android:label="{app_name}"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>''',
        f'app/src/main/java/{package_path}/MainActivity.kt':f'''package {app_id}\nimport android.app.Activity\nimport android.os.Bundle\nimport android.widget.TextView\nclass MainActivity: Activity() {{ override fun onCreate(savedInstanceState: Bundle?) {{ super.onCreate(savedInstanceState); setContentView(TextView(this).apply {{ text="{app_name}"; textSize=28f; setPadding(48,96,48,48) }}) }} }}\n''',
        'app/src/main/res/values/styles.xml':'<resources><style name="AppTheme" parent="android:style/Theme.Material.Light.NoActionBar"><item name="android:fontFamily">sans</item></style></resources>',
        '.github/workflows/android.yml':'name: android\non: [push]\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with: {distribution: temurin, java-version: "17"}\n      - uses: gradle/actions/setup-gradle@v4\n      - run: ./gradlew bundleRelease\n',
        'README.md':'# Android source\nGenerated source. Release signing secrets must be injected by CI; never commit a keystore or passwords.\n',
    }

def ios_project(*, app_name: str='Omni App', bundle_id: str='ai.omnicreator.app') -> dict[str,str]:
    bid=_safe_id(bundle_id)
    safe_name=re.sub(r'[^A-Za-z0-9 ]','',app_name) or 'Omni App'
    return {
        'project.yml':f'''name: OmniApp\noptions:\n  bundleIdPrefix: {bid.rsplit('.',1)[0] if '.' in bid else bid}\ntargets:\n  OmniApp:\n    type: application\n    platform: iOS\n    deploymentTarget: "16.0"\n    sources: [Sources]\n    settings:\n      base:\n        PRODUCT_BUNDLE_IDENTIFIER: {bid}\n        PRODUCT_NAME: "{safe_name}"\n''',
        'Sources/OmniApp.swift':f'''import SwiftUI\n@main struct OmniApp: App {{ var body: some Scene {{ WindowGroup {{ ContentView() }} }} }}\nstruct ContentView: View {{ var body: some View {{ VStack(spacing: 20) {{ Text("{safe_name}").font(.largeTitle).bold(); Text("Generated by Omni Creator") }}.padding() }} }}\n''',
        '.github/workflows/ios-source-check.yml':'name: ios-source-check\non: [push]\njobs:\n  check:\n    runs-on: macos-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: brew install xcodegen\n      - run: xcodegen generate\n      - run: xcodebuild -project OmniApp.xcodeproj -scheme OmniApp -sdk iphonesimulator -destination "platform=iOS Simulator,name=iPhone 16" build CODE_SIGNING_ALLOWED=NO\n',
        'README.md':'# iOS source\nUses XcodeGen. Signed IPA/App Store upload requires Apple credentials and must run on macOS/Xcode.\n',
    }

def game_project(engine: str, *, title: str='Omni Game') -> dict[str,str]:
    e=engine.lower()
    if e=='godot':
        return {
            'project.godot':f'[application]\nconfig/name="{title}"\nconfig/features=PackedStringArray("4.3")\nrun/main_scene="res://Main.tscn"\n[display]\nwindow/size/viewport_width=1280\nwindow/size/viewport_height=720\n[rendering]\nrenderer/rendering_method="gl_compatibility"\n',
            'Main.tscn':'[gd_scene load_steps=2 format=3]\n\n[ext_resource path="res://Player.gd" type="Script" id="1"]\n[node name="Main" type="Node3D"]\n[node name="Player" type="CharacterBody3D" parent="."]\nscript = ExtResource("1")\n',
            'Player.gd':'extends CharacterBody3D\nconst SPEED=5.0\nfunc _physics_process(_delta):\n    var v=Input.get_vector("ui_left","ui_right","ui_up","ui_down")\n    velocity.x=v.x*SPEED; velocity.z=v.y*SPEED; move_and_slide()\n',
        }
    if e=='unity':
        return {
            'ProjectSettings/ProjectVersion.txt':'m_EditorVersion: 6000.0.23f1\n',
            'Assets/Scripts/PlayerController.cs':'using UnityEngine; public class PlayerController:MonoBehaviour { public float speed=5f; void Update(){ var x=Input.GetAxis("Horizontal"); var z=Input.GetAxis("Vertical"); transform.Translate(new Vector3(x,0,z)*speed*Time.deltaTime); } }\n',
            'Assets/README.md':f'# {title}\nGenerated Unity source skeleton.\n',
        }
    if e=='unreal':
        slug=re.sub(r'[^A-Za-z0-9]','',title) or 'OmniGame'
        return {
            f'{slug}.uproject':json.dumps({'FileVersion':3,'EngineAssociation':'5.5','Category':'Games','Description':title,'Modules':[{'Name':slug,'Type':'Runtime','LoadingPhase':'Default'}]},indent=2),
            'Config/DefaultEngine.ini':'[/Script/EngineSettings.GameMapsSettings]\nGameDefaultMap=/Game/Maps/Main\n',
            f'Source/{slug}/{slug}.Build.cs':f'using UnrealBuildTool; public class {slug}:ModuleRules {{ public {slug}(ReadOnlyTargetRules Target):base(Target) {{ PCHUsage=PCHUsageMode.UseExplicitOrSharedPCHs; PublicDependencyModuleNames.AddRange(new string[]{{"Core","CoreUObject","Engine","InputCore"}}); }} }}\n',
            'README.md':f'# {title}\nGenerated Unreal Engine source skeleton. Console publishing requires platform-holder SDK access and certification.\n',
        }
    raise ValueError('engine must be godot, unity or unreal')


def omni_android_release_project() -> dict[str, str]:
    """Android Studio source for the Omni Creator client itself.

    Mirrors the V10 release contract while keeping signing material external.
    """
    prefix = 'omni-android/'
    app_id = 'ai.omnicreator.mobile'
    package_path = app_id.replace('.', '/')
    files = {
        'settings.gradle.kts': 'pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }\ndependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }\nrootProject.name="OmniCreator"\ninclude(":app")\n',
        'build.gradle.kts': 'plugins { id("com.android.application") version "8.7.3" apply false }\n',
        'app/build.gradle.kts': f'''plugins {{ id("com.android.application") }}\nandroid {{ namespace="{app_id}"; compileSdk=35\n defaultConfig {{ applicationId="{app_id}"; minSdk=26; targetSdk=35; versionCode=1; versionName="1.0" }}\n signingConfigs {{ create("release") {{\n   val ks=System.getenv("OMNI_ANDROID_KEYSTORE"); if (ks != null) storeFile=file(ks)\n   storePassword=System.getenv("OMNI_ANDROID_STORE_PASSWORD")\n   keyAlias=System.getenv("OMNI_ANDROID_KEY_ALIAS")\n   keyPassword=System.getenv("OMNI_ANDROID_KEY_PASSWORD")\n }} }}\n buildTypes {{ release {{ signingConfig=signingConfigs.getByName("release"); isMinifyEnabled=false }} }} }}\n''',
        'app/src/main/AndroidManifest.xml': '''<manifest xmlns:android="http://schemas.android.com/apk/res/android"><uses-permission android:name="android.permission.INTERNET"/><uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/><application android:usesCleartextTraffic="false" android:label="Omni Creator"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>''',
        f'app/src/main/java/{package_path}/MainActivity.java': f'''package {app_id};\nimport android.Manifest;\nimport android.app.Activity;\nimport android.os.Bundle;\nimport android.webkit.*;\nimport android.content.pm.PackageManager;\nimport android.content.Intent;\nimport android.net.Uri;\nimport android.provider.Settings;\npublic class MainActivity extends Activity {{\n  private WebView web; private ValueCallback<Uri[]> fileChooser;\n  @Override public void onCreate(Bundle b) {{ super.onCreate(b); web=new WebView(this); setContentView(web); WebSettings s=web.getSettings(); s.setJavaScriptEnabled(true); s.setGeolocationEnabled(true);\n    web.setWebChromeClient(new WebChromeClient() {{\n      @Override public void onGeolocationPermissionsShowPrompt(String origin, GeolocationPermissions.Callback cb) {{ if (checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED) requestPermissions(new String[]{{Manifest.permission.ACCESS_FINE_LOCATION}},501); cb.invoke(origin,true,false); }}\n      @Override public boolean onShowFileChooser(WebView view, ValueCallback<Uri[]> callback, FileChooserParams params) {{ fileChooser=callback; startActivityForResult(params.createIntent(),502); return true; }}\n    }}); web.loadUrl("https://app.omnicreator.ai"); }}\n}}\n''',
        'README.md': '# Omni Creator Android\nAndroid Studio source. Signed AAB requires external keystore secrets.\n',
    }
    out = {prefix + k: v for k, v in files.items()}
    out['.github/workflows/omni-android-aab.yml'] = '''name: omni-android-aab\non: [workflow_dispatch]\njobs:\n  aab:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with: {distribution: temurin, java-version: "17"}\n      - uses: gradle/actions/setup-gradle@v4\n        with: {gradle-version: "8.9"}\n      - run: cd omni-android && gradle bundleRelease\n        env:\n          OMNI_ANDROID_KEYSTORE: ${{ secrets.OMNI_ANDROID_KEYSTORE }}\n          OMNI_ANDROID_STORE_PASSWORD: ${{ secrets.OMNI_ANDROID_STORE_PASSWORD }}\n          OMNI_ANDROID_KEY_ALIAS: ${{ secrets.OMNI_ANDROID_KEY_ALIAS }}\n          OMNI_ANDROID_KEY_PASSWORD: ${{ secrets.OMNI_ANDROID_KEY_PASSWORD }}\n'''
    return out
